<script src="https://cdn.jsdelivr.net/npm/chart.js@4.5.0/dist/chart.umd.min.js"></script>
<script>
(()=>{const M=MyLedger;let trendChart,categoryChart;const from=document.querySelector('#reportFrom'),to=document.querySelector('#reportTo'),preset=document.querySelector('#periodPreset');function iso(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}function applyPreset(){const now=new Date(),a=new Date(now),b=new Date(now);if(preset.value==='today'){}else if(preset.value==='week'){const day=(now.getDay()+6)%7;a.setDate(now.getDate()-day);b.setDate(a.getDate()+6)}else if(preset.value==='month'){a.setDate(1);b.setMonth(now.getMonth()+1,0)}else if(preset.value==='year'){a.setMonth(0,1);b.setMonth(11,31)}else return;from.value=iso(a);to.value=iso(b)}async function load(){const qs=M.query({from:from.value,to:to.value});try{const [summary,cats,trend,nw,cf]=await Promise.all([M.request('/ajax/reports/summary?'+qs),M.request('/ajax/reports/expense-by-category?'+qs),M.request('/ajax/reports/monthly-trend?months=12'),M.request('/ajax/reports/net-worth?as_of='+to.value),M.request('/ajax/reports/cash-flow?'+qs)]);document.querySelector('#reportIncome').textContent=M.money(summary.income);document.querySelector('#reportExpense').textContent=M.money(summary.expense);document.querySelector('#reportNet').textContent=M.money(summary.net_cash_surplus);document.querySelector('#reportNetWorth').textContent=M.money(nw.net_worth);trendChart?.destroy();trendChart=new Chart(document.querySelector('#trendChart'),{type:'line',data:{labels:trend.map(x=>x.month),datasets:[{label:'Income',data:trend.map(x=>x.income),tension:.35},{label:'Expense',data:trend.map(x=>x.expense),tension:.35}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true}}}});categoryChart?.destroy();categoryChart=new Chart(document.querySelector('#categoryChart'),{type:'doughnut',data:{labels:cats.map(x=>x.name),datasets:[{data:cats.map(x=>x.total)}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});document.querySelector('#cashFlowReport').innerHTML=`<div class="row g-3"><div class="col-4"><div class="small text-secondary">External inflow</div><div class="h5 text-success mt-1">${M.money(cf.inflow)}</div></div><div class="col-4"><div class="small text-secondary">External outflow</div><div class="h5 text-danger mt-1">${M.money(cf.outflow)}</div></div><div class="col-4"><div class="small text-secondary">Net cash flow</div><div class="h5 mt-1">${M.money(cf.net)}</div></div></div><hr><div class="small text-secondary">Internal transfers excluded from inflow/outflow: ${M.money(cf.internal_transfers)}</div>`;document.querySelector('#netWorthBreakdown').innerHTML=`<div class="d-flex justify-content-between mb-2"><span>Assets</span><strong>${M.money(nw.asset_total)}</strong></div>${nw.assets.slice(0,5).map(x=>`<div class="d-flex justify-content-between small text-secondary py-1"><span>${M.esc(x.name)}</span><span>${M.money(x.balance)}</span></div>`).join('')}<hr><div class="d-flex justify-content-between mb-2"><span>Liabilities</span><strong>${M.money(nw.liability_total)}</strong></div>${nw.liabilities.slice(0,5).map(x=>`<div class="d-flex justify-content-between small text-secondary py-1"><span>${M.esc(x.name)}</span><span>${M.money(x.balance)}</span></div>`).join('')}`;document.querySelector('#csvExport').href='{{ route('exports.transactions') }}?'+qs;}catch(e){M.toast(e.message,'danger')}}preset.onchange=()=>{applyPreset();if(preset.value!=='custom')load()};document.querySelector('#runReport').onclick=load;applyPreset();load()})();
</script>
@endpush
